-- name: UpsertAppRumSettingKey :one
-- Enable/rotate: one row per app. On the first call this creates the row with a fresh key; on a
-- later rotation it replaces key_hash and forces enabled = true (rotating implies turning it on).
INSERT INTO app_rum_settings (app_id, team_id, enabled, key_hash, created_by)
VALUES (sqlc.arg('app_id'), sqlc.arg('team_id'), true, sqlc.arg('key_hash'), sqlc.arg('created_by'))
ON CONFLICT (app_id) DO UPDATE SET enabled = true, key_hash = sqlc.arg('key_hash'), updated_at = now()
RETURNING *;

-- name: SetAppRumSettingEnabled :one
-- Toggling off never touches the key: re-enabling without rotating still works with the same
-- snippet already pasted into the app.
UPDATE app_rum_settings SET enabled = sqlc.arg('enabled'), updated_at = now()
WHERE team_id = sqlc.arg('team_id') AND app_id = sqlc.arg('app_id')
RETURNING *;

-- name: AppRumSettingByKeyHash :one
-- tenancy.Scope{TokenHash: ...} (not System), public ingest endpoint (POST /api/rum/{key},
-- internal/rum), exactly like monitors' MonitorByPingToken: resolves a presented key to its app
-- and team, and whether RUM is enabled — nothing else about the app or team. See the RLS policy
-- app_rum_settings_key_hash_select.
SELECT app_id, team_id, enabled FROM app_rum_settings WHERE key_hash = sqlc.arg('key_hash');
